"""Render original catalogue thumbnails from the studio's own geometry and materials."""
import base64,io,os
from pathlib import Path
from PIL import Image
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'assets/studio-parts';OUT.mkdir(exist_ok=True)
BASE=os.environ.get('GREENSHIFT_TEST_URL','http://localhost:4175/GreenShift-/').rstrip('/')+'/'
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader']);p=b.new_page();p.goto(BASE+'assets/renovation-studio.html?guided=1&lang=en');p.wait_for_function('window.GreenShiftRender&&window.GreenShiftConcepts');items=p.evaluate('''()=>{const T=THREE,R=GreenShiftRender,A=GreenShiftAssembly,C=GreenShiftConcepts,renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setSize(360,270);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;const scene=new T.Scene();scene.background=new T.Color(0xf5f4ef);const env=R.environment(renderer,scene);scene.add(new T.HemisphereLight(0xffffff,0xb4b6a7,1.2));const sun=new T.DirectionalLight(0xfff4df,3);sun.position.set(-4,7,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=sun.shadow.camera.bottom=-8;sun.shadow.camera.right=sun.shadow.camera.top=8;sun.shadow.normalBias=.02;scene.add(sun);const ground=new T.Mesh(new T.PlaneGeometry(40,40),R.surface('plaster',0xf4f3ee));ground.rotation.x=-Math.PI/2;ground.position.y=-.02;ground.receiveShadow=true;scene.add(ground);const camera=new T.PerspectiveCamera(34,4/3,.05,100),out={};
for(const type of Object.keys(A.types)){let root;if(C.spec[type])root=R.furniture(C.reference(type,0,0,{y:0}),'japandi');else{root=new T.Group();const w=type==='wall'?2.4:type==='glass'?2:3,h=['slab','roof'].includes(type)?.18:2.7,d=type==='wall'?.15:type==='glass'?.04:2.3;let geo;if(type==='wall'){const s=new T.Shape();s.moveTo(-w/2,0);s.lineTo(w/2,0);s.lineTo(w/2,h);s.lineTo(-w/2,h);s.closePath();const hole=new T.Path();hole.moveTo(-.4,0);hole.lineTo(-.4,1.95);hole.lineTo(.4,1.95);hole.lineTo(.4,0);hole.closePath();s.holes.push(hole);geo=new T.ExtrudeGeometry(s,{depth:d,bevelEnabled:false});geo.translate(0,0,-d/2);}else{geo=new T.BoxGeometry(w,h,d);geo.translate(0,h/2,0);}R.projectUV(geo);const mesh=new T.Mesh(geo,type==='glass'?R.glass():R.surface(type==='slab'?'wood':'plaster',type==='roof'?0xc5ccc4:0xffffff));mesh.castShadow=type!=='glass';mesh.receiveShadow=true;root.add(mesh);if(type==='glass'){for(const [width,height,x,y] of [[.04,h,-w/2,h/2],[.04,h,w/2,h/2],[w,.04,0,.02],[w,.04,0,h-.02]]){const frame=new T.Mesh(new T.BoxGeometry(width,height,.06),R.metal(0x56635b));frame.position.set(x,y,0);root.add(frame);}}}
 const box=new T.Box3().setFromObject(root),center=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),max=Math.max(size.x,size.y,size.z);root.position.sub(new T.Vector3(center.x,box.min.y,center.z));scene.add(root);camera.position.set(max*1.45,max*1.05,max*1.65);camera.lookAt(0,size.y*.4,0);renderer.render(scene,camera);out[type]=renderer.domElement.toDataURL('image/png');scene.remove(root);root.traverse(o=>{if(o.geometry&&!o.geometry.userData.shared)o.geometry.dispose();});}
env.dispose();renderer.dispose();return out;}''')
 for key,data in items.items():im=Image.open(io.BytesIO(base64.b64decode(data.split(',')[1])));im.save(OUT/(key+'.webp'),quality=91)
 print('Rendered '+str(len(items))+' original studio catalogue previews.');b.close()
